        this.accountNumber = accountNumber;
        this.accountHolder = accountHolder;
        this.receiptRequested = receiptRequested;
        this.setPaidAmount(paidAmount);
    }
    @Override
    public String getImpUid() {
        return this.impUid;
    }

}

